import matplotlib.pyplot as plt


def calculate_cumulative_gc_skew(sequence):
    """
    Calculates the cumulative GC skew of a DNA sequence.
    Formula: Steps +1 for G, -1 for C, 0 for A/T.
    The global minimum is the predicted Origin of Replication (ori).
    """
    skew = [0]
    current_skew = 0
    min_skew = 0
    ori_index = 0

    # Iterate through the sequence to build the skew profile
    for i, base in enumerate(sequence):
        base = base.upper()
        if base == "G":
            current_skew += 1
        elif base == "C":
            current_skew -= 1

        skew.append(current_skew)

        # Track the minimum skew to find the ori
        if current_skew < min_skew:
            min_skew = current_skew
            ori_index = i + 1  # +1 because skew array is 1-based relative to seq

    return skew, ori_index


# --- Example ---
if __name__ == "__main__":
    genome_sequence = (
        ""
    )

    skew_data, predicted_ori = calculate_cumulative_gc_skew(genome_sequence)
    window_size = 500

    # Calculate boundaries within sequence lengths
    start_pos = max(0, predicted_ori - (window_size // 2))
    end_pos = min(len(genome_sequence), predicted_ori + (window_size // 2))

    # Extract the actual sequence surrounding the index
    ori_sequence = genome_sequence[start_pos:end_pos]

    print(f"Sequence Length: {len(genome_sequence)}")
    print(f"Predicted Origin of Replication (ori) index: {predicted_ori}")
    print(f"Extracted window size: {len(ori_sequence)} bp")
    print(f"Predicted ori Sequence:\n{ori_sequence}")

    # Visualization
    try:
        plt.figure(figsize=(10, 5))
        plt.plot(skew_data, label="Cumulative GC Skew")
        plt.axvline(
            x=predicted_ori,
            color="r",
            linestyle="--",
            label=f"Predicted ori ({predicted_ori})",
        )
        plt.title("Cumulative GC Skew Diagram")
        plt.xlabel("Genome Position (bp)")
        plt.ylabel("Cumulative Skew (G - C)")
        plt.legend()
        plt.grid(True)
        plt.show()
        print("Plot generated successfully.")
    except Exception as e:
        print("Matplotlib not found or failed. Install it to see the graph.")
